  'dsup.q3': { pt: 'Posso alterar o preço das minhas consultas?', en: 'Can I change my consultation prices?', fr: 'Puis-je modifier le prix de mes consultations ?', es: '¿Puedo cambiar el precio de mis consultas?' },
