  'cgate.go_dashboard': { pt: 'Ir para o Painel', en: 'Go to Dashboard', fr: 'Aller au tableau de bord', es: 'Ir al panel' },
  'cgate.title': { pt: 'Antes de continuar', en: 'Before you continue', fr: 'Avant de continuer', es: 'Antes de continuar' },
  'cgate.intro': { pt: 'A KAYA trata dados de saúde sensíveis e presta serviços de coordenação de cuidados. Leia e aceite os seguintes termos antes de aceder à sua conta.', en: 'KAYA processes sensitive health data and provides care-coordination services. Please read and accept the following terms before accessing your account.', fr: 'KAYA traite des données de santé sensibles et fournit des services de coordination des soins. Veuillez lire et accepter les conditions suivantes avant d’accéder à votre compte.', es: 'KAYA trata datos de salud sensibles y presta servicios de coordinación de cuidados. Lea y acepte los siguientes términos antes de acceder a su cuenta.' },
  'cgate.emergency_bold': { pt: '🚨 Não é um serviço de emergência.', en: '🚨 Not an emergency service.', fr: '🚨 Ce n’est pas un service d’urgence.', es: '🚨 No es un servicio de emergencia.' },
  'cgate.emergency_rest': { pt: 'Em caso de emergência médica, ligue imediatamente para o número de emergência local.', en: 'In a medical emergency, call your local emergency number immediately.', fr: 'En cas d’urgence médicale, appelez immédiatement votre numéro d’urgence local.', es: 'En caso de emergencia médica, llame de inmediato a su número de emergencia local.' },
