  'cgate.link_privacy': { pt: 'Política de Privacidade', en: 'Privacy Policy', fr: 'Politique de confidentialité', es: 'Política de privacidad' },
  'cgate.link_consents': { pt: 'Consentimentos', en: 'Consents', fr: 'Consentements', es: 'Consentimientos' },
  'cgate.c_terms_pre': { pt: 'Li e aceito os', en: 'I have read and accept the', fr: 'J’ai lu et j’accepte les', es: 'He leído y acepto los' },
  'cgate.c_terms_desc': { pt: 'Regula a utilização da plataforma, as responsabilidades da conta e o âmbito do serviço.', en: 'Governs platform use, account responsibilities, and the scope of the service.', fr: 'Régit l’utilisation de la plateforme, les responsabilités du compte et la portée du service.', es: 'Regula el uso de la plataforma, las responsabilidades de la cuenta y el alcance del servicio.' },
  'cgate.c_disclaimer_pre': { pt: 'Reconheço o', en: 'I acknowledge the', fr: 'Je reconnais l’', es: 'Reconozco el' },
  'cgate.c_disclaimer_desc': { pt: 'Esta plataforma não é um serviço de emergência e não substitui os cuidados médicos presenciais. As medições de dispositivos podem conter erros e devem ser revistas por um profissional.', en: 'This platform is not an emergency service and does not replace in-person medical care. Device readings may contain errors and should be reviewed by a professional.', fr: 'Cette plateforme n’est pas un service d’urgence et ne remplace pas les soins médicaux en personne. Les mesures des appareils peuvent contenir des erreurs et doivent être vérifiées par un professionnel.', es: 'Esta plataforma no es un servicio de emergencia y no sustituye la atención médica presencial. Las mediciones de dispositivos pueden contener errores y deben ser revisadas por un profesional.' },
  'cgate.c_healthdata_pre': { pt: 'Consinto o tratamento dos meus dados de saúde conforme descrito na', en: 'I consent to the processing of my health data as described in the', fr: 'Je consens au traitement de mes données de santé comme décrit dans la', es: 'Consiento el tratamiento de mis datos de salud como se describe en la' },
  'cgate.c_healthdata_desc': { pt: 'Os dados de saúde são tratados para prestar serviços de coordenação de cuidados. Pode solicitar a eliminação ou exportação a qualquer momento nas Definições.', en: 'Health data is processed to provide care-coordination services. You can request deletion or export at any time in Settings.', fr: 'Les données de santé sont traitées pour fournir des services de coordination des soins. Vous pouvez demander leur suppression ou leur export à tout moment dans les Paramètres.', es: 'Los datos de salud se tratan para prestar servicios de coordinación de cuidados. Puede solicitar su eliminación o exportación en cualquier momento en Ajustes.' },
  'cgate.c_privacy_pre': { pt: 'Li e aceito a', en: 'I have read and accept the', fr: 'J’ai lu et j’accepte la', es: 'He leído y acepto la' },
  'cgate.c_privacy_desc': { pt: 'Descreve como recolhemos, usamos, armazenamos e protegemos os seus dados pessoais, em conformidade com a legislação de proteção de dados aplicável.', en: 'Describes how we collect, use, store, and protect your personal data, in line with applicable data-protection law.', fr: 'Décrit comment nous collectons, utilisons, stockons et protégeons vos données personnelles, conformément à la législation applicable sur la protection des données.', es: 'Describe cómo recopilamos, usamos, almacenamos y protegemos sus datos personales, conforme a la legislación de protección de datos aplicable.' },
  'cgate.c_telemed_label': { pt: 'Consinto receber serviços de telemedicina através desta plataforma', en: 'I consent to receiving telemedicine services through this platform', fr: 'Je consens à recevoir des services de télémédecine via cette plateforme', es: 'Consiento recibir servicios de telemedicina a través de esta plataforma' },
  'cgate.c_telemed_desc': { pt: 'As teleconsultas são prestadas por profissionais licenciados. Reconhece as limitações do atendimento remoto e o seu direito a alternativas presenciais.', en: 'Teleconsultations are provided by licensed professionals. You acknowledge the limitations of remote care and your right to in-person alternatives.', fr: 'Les téléconsultations sont assurées par des professionnels agréés. Vous reconnaissez les limites des soins à distance et votre droit à des alternatives en personne.', es: 'Las teleconsultas son prestadas por profesionales autorizados. Reconoce las limitaciones de la atención remota y su derecho a alternativas presenciales.' },
  'cgate.error_all': { pt: 'Aceite todos os cinco itens para continuar.', en: 'Accept all five items to continue.', fr: 'Acceptez les cinq éléments pour continuer.', es: 'Acepte los cinco elementos para continuar.' },
  'cgate.save_error': { pt: 'Não foi possível guardar os consentimentos. Tente novamente.', en: 'Failed to save consents. Please try again.', fr: 'Échec de l’enregistrement des consentements. Réessayez.', es: 'No se pudieron guardar los consentimientos. Inténtelo de nuevo.' },
  'cgate.accept_continue': { pt: 'Aceitar e Continuar', en: 'Accept and Continue', fr: 'Accepter et continuer', es: 'Aceptar y continuar' },
  'cgate.already_tag': { pt: '(já aceite)', en: '(already accepted)', fr: '(déjà accepté)', es: '(ya aceptado)' },
  'cgate.footer_pre': { pt: 'Estes consentimentos são registados com o seu endereço IP e data/hora, conforme exigido para fins de auditoria. Pode rever os consentimentos aceites a qualquer momento na secção', en: 'These consents are recorded with your IP address and timestamp, as required for audit purposes. You can review accepted consents at any time in the', fr: 'Ces consentements sont enregistrés avec votre adresse IP et l’horodatage, comme l’exige l’audit. Vous pouvez consulter les consentements acceptés à tout moment dans la section', es: 'Estos consentimientos se registran con su dirección IP y fecha/hora, según se exige para fines de auditoría. Puede revisar los consentimientos aceptados en cualquier momento en la sección' },

