  'urg.s5_title': { pt: 'Chegada organizada', en: 'Organised arrival', fr: 'Arrivée organisée', es: 'Llegada organizada' },
  'urg.s5_desc': { pt: 'Recepção informada. Processo mais rápido e seguro.', en: 'Reception informed. A faster, safer process.', fr: 'Accueil informé. Un processus plus rapide et sûr.', es: 'Recepción informada. Un proceso más rápido y seguro.' },
  'urg.why_tag': { pt: 'Porquê é importante', en: 'Why it matters', fr: 'Pourquoi c’est important', es: 'Por qué es importante' },
  'urg.why_title': { pt: 'Em Luanda, cada minuto conta.', en: 'In Luanda, every minute counts.', fr: 'À Luanda, chaque minute compte.', es: 'En Luanda, cada minuto cuenta.' },
  'urg.why_desc': { pt: 'Em emergências médicas, chegar a um hospital sem aviso prévio pode significar longos tempos de espera. O pré-alerta muda isso.', en: 'In medical emergencies, arriving at a hospital unannounced can mean long waits. The pre-alert changes that.', fr: 'En cas d’urgence médicale, arriver à l’hôpital sans prévenir peut signifier de longues attentes. La pré-alerte change cela.', es: 'En emergencias médicas, llegar a un hospital sin aviso puede suponer largas esperas. El pre-aviso cambia eso.' },
  'urg.t1_label': { pt: 'Menos tempo de espera', en: 'Less waiting time', fr: 'Moins d’attente', es: 'Menos tiempo de espera' },
  'urg.t1_desc': { pt: 'Hospital preparado para receber antes da chegada.', en: 'Hospital ready to receive you before you arrive.', fr: 'Hôpital prêt à vous recevoir avant votre arrivée.', es: 'Hospital preparado para recibirle antes de llegar.' },
  'urg.t2_label': { pt: 'Mais segurança clínica', en: 'Greater clinical safety', fr: 'Plus de sécurité clinique', es: 'Mayor seguridad clínica' },
  'urg.t2_desc': { pt: 'Médicos com contexto antes de o ver.', en: 'Doctors have context before seeing you.', fr: 'Les médecins ont le contexte avant de vous voir.', es: 'Los médicos tienen contexto antes de verle.' },
  'urg.t3_label': { pt: 'Rede em crescimento', en: 'Growing network', fr: 'Réseau en croissance', es: 'Red en crecimiento' },
  'urg.t3_desc': { pt: 'Estamos a estabelecer parcerias com hospitais e urgências em Angola.', en: 'We’re establishing partnerships with hospitals and ERs across Angola.', fr: 'Nous établissons des partenariats avec des hôpitaux et urgences en Angola.', es: 'Estamos estableciendo alianzas con hospitales y urgencias en Angola.' },
  'urg.t4_label': { pt: 'Simples de activar', en: 'Simple to activate', fr: 'Simple à activer', es: 'Fácil de activar' },
  'urg.t4_desc': { pt: 'Menos de 2 minutos no portal ou na app.', en: 'Under 2 minutes on the portal or app.', fr: 'Moins de 2 minutes sur le portail ou l’app.', es: 'Menos de 2 minutos en el portal o la app.' },
  'urg.final_title': { pt: 'Esteja preparado antes de precisar.', en: 'Be prepared before you need it.', fr: 'Soyez prêt avant d’en avoir besoin.', es: 'Esté preparado antes de necesitarlo.' },
  'urg.final_desc': { pt: 'Crie o seu perfil agora. Em caso de urgência, os dados já estão prontos para enviar.', en: 'Create your profile now. In an emergency, your data is ready to send.', fr: 'Créez votre profil maintenant. En cas d’urgence, vos données sont prêtes à être envoyées.', es: 'Cree su perfil ahora. En una urgencia, sus datos ya están listos para enviar.' },
  'urg.final_cta': { pt: 'Criar conta gratuita', en: 'Create a free account', fr: 'Créer un compte gratuit', es: 'Crear cuenta gratuita' },

