  'cc.f1_desc': { pt: 'Medicação crónica reabastecida sem deslocação. O médico valida e emite a receita digitalmente.', en: 'Chronic medication refilled without travel. The doctor validates and issues the prescription digitally.', fr: 'Médicaments chroniques réapprovisionnés sans déplacement. Le médecin valide et délivre l’ordonnance numériquement.', es: 'Medicación crónica reabastecida sin desplazamientos. El médico valida y emite la receta digitalmente.' },
  'cc.f2_title': { pt: 'Check-ins mensais com o médico', en: 'Monthly check-ins with the doctor', fr: 'Points mensuels avec le médecin', es: 'Chequeos mensuales con el médico' },
  'cc.f2_desc': { pt: 'Consulta de acompanhamento mensal incluída. O médico analisa as suas leituras e ajusta o plano.', en: 'Monthly follow-up consultation included. The doctor reviews your readings and adjusts the plan.', fr: 'Consultation de suivi mensuelle incluse. Le médecin analyse vos mesures et ajuste le plan.', es: 'Consulta de seguimiento mensual incluida. El médico analiza sus lecturas y ajusta el plan.' },
  'cc.f3_title': { pt: 'Gráficos de evolução das leituras', en: 'Reading-trend charts', fr: 'Graphiques d’évolution des mesures', es: 'Gráficos de evolución de las lecturas' },
  'cc.f3_desc': { pt: 'Veja como a tensão, glicemia e outros vitais evoluem ao longo dos meses. Resultados visíveis.', en: 'See how blood pressure, glucose, and other vitals evolve over the months. Visible results.', fr: 'Voyez comment la tension, la glycémie et d’autres constantes évoluent au fil des mois. Résultats visibles.', es: 'Vea cómo evolucionan la tensión, la glucemia y otros signos vitales a lo largo de los meses. Resultados visibles.' },
  'cc.f4_title': { pt: 'Alertas de risco personalizados', en: 'Personalised risk alerts', fr: 'Alertes de risque personnalisées', es: 'Alertas de riesgo personalizadas' },
  'cc.f4_desc': { pt: 'Recebe notificação imediata quando uma leitura está fora do intervalo seguro para o seu perfil.', en: 'Get an immediate notification when a reading is outside the safe range for your profile.', fr: 'Recevez une notification immédiate lorsqu’une mesure est hors de la plage sûre pour votre profil.', es: 'Reciba una notificación inmediata cuando una lectura está fuera del rango seguro para su perfil.' },
  'cc.f5_title': { pt: 'Monitorização familiar', en: 'Family monitoring', fr: 'Suivi familial', es: 'Monitoreo familiar' },
  'cc.f5_desc': { pt: 'Um familiar pode acompanhar as suas leituras. Ideal para idosos ou doentes dependentes.', en: 'A family member can follow your readings. Ideal for the elderly or dependent patients.', fr: 'Un proche peut suivre vos mesures. Idéal pour les personnes âgées ou dépendantes.', es: 'Un familiar puede seguir sus lecturas. Ideal para personas mayores o pacientes dependientes.' },
  'cc.f6_title': { pt: 'Plano de saúde personalizado', en: 'Personalised health plan', fr: 'Plan de santé personnalisé', es: 'Plan de salud personalizado' },
  'cc.f6_desc': { pt: 'O médico define os intervalos seguros, frequência de medição e medicação para o seu caso.', en: 'The doctor sets the safe ranges, measurement frequency, and medication for your case.', fr: 'Le médecin définit les plages sûres, la fréquence des mesures et les médicaments pour votre cas.', es: 'El médico define los rangos seguros, la frecuencia de medición y la medicación para su caso.' },
  'cc.journey_tag': { pt: 'Como funciona', en: 'How it works', fr: 'Comment ça marche', es: 'Cómo funciona' },
  'cc.journey_title': { pt: 'Do diagnóstico ao acompanhamento contínuo.', en: 'From diagnosis to continuous follow-up.', fr: 'Du diagnostic au suivi continu.', es: 'Del diagnóstico al seguimiento continuo.' },
  'cc.j1_title': { pt: 'Registe a sua condição', en: 'Record your condition', fr: 'Enregistrez votre condition', es: 'Registre su condición' },
