  'cc.j2_title': { pt: 'Meça e envie vitais', en: 'Measure and send vitals', fr: 'Mesurez et envoyez vos constantes', es: 'Mida y envíe signos vitales' },
  'cc.j2_desc': { pt: 'Use os seus dispositivos existentes ou adquira um kit KAYA. Dados sincronizados automaticamente.', en: 'Use your existing devices or get a KAYA kit. Data synced automatically.', fr: 'Utilisez vos appareils existants ou procurez-vous un kit KAYA. Données synchronisées automatiquement.', es: 'Use sus dispositivos existentes o adquiera un kit KAYA. Datos sincronizados automáticamente.' },
