  'cc.j3_desc': { pt: 'Reunião digital mensal. O médico vê toda a evolução e ajusta o tratamento.', en: 'Monthly digital meeting. The doctor sees the full progress and adjusts treatment.', fr: 'Réunion numérique mensuelle. Le médecin voit toute l’évolution et ajuste le traitement.', es: 'Reunión digital mensual. El médico ve toda la evolución y ajusta el tratamiento.' },
