  'cc.plan_desc': { pt: 'Inclui check-ins mensais, renovação de receita, vitals tracking, alertas de risco e historial completo.', en: 'Includes monthly check-ins, prescription renewal, vitals tracking, risk alerts, and full history.', fr: 'Comprend des points mensuels, le renouvellement d’ordonnance, le suivi des constantes, les alertes de risque et l’historique complet.', es: 'Incluye chequeos mensuales, renovación de receta, seguimiento de signos vitales, alertas de riesgo e historial completo.' },
